package com.backend.gapfinder.view.dto;

import java.time.LocalDateTime;

import com.backend.gapfinder.model.models.ChatMessageModel;

import lombok.Data;

@Data
public class ChatMessageDTO {

    // Id given by the server (the app uses the last one as afterId when polling)
    private Long id;

    // Id generated by the app (UUID)
    private String clientId;

    // Id of the student who sent the message
    private Long senderId;

    // Id of the student who receives the message
    private Long receiverId;

    // Text of the message
    private String content;

    // Date and time when the server stored the message
    private LocalDateTime createdAt;

    public static ChatMessageDTO from(ChatMessageModel message) {
        ChatMessageDTO dto = new ChatMessageDTO();
        dto.setId(message.getId());
        dto.setClientId(message.getClientId());
        dto.setSenderId(message.getSender().getId());
        dto.setReceiverId(message.getReceiver().getId());
        dto.setContent(message.getContent());
        dto.setCreatedAt(message.getCreatedAt());
        return dto;
    }
}
